function factorial(n) {
  let result = 1;
  for (let i = 2; i <= n; i++) {
    result *= i;
  }
  return result;
}

function futureValue(investment, rate, years) {
  let value = investment;
  for (let i = 1; i <= years; i++) {
    value += value * rate / 100;
  }
  return Number(value.toFixed(2));
}

