    results.push("Buzz");
  } else {
    results.push(n);
  }
}

const entries = ["88", "abc", "100", "105", "0", "-5"];
const scores = [];
for (const entry of entries) {
  const score = parseInt(entry);
  if (!isNaN(score) && score >= 0 && score <= 100) {
    scores.push(score);
  }
}
let total = 0;
for (const score of scores) {
  total += score;
}
const average = Math.round(total / scores.length);
document.querySelector("#result").textContent = `Scores: ${scores.join(", ")} — Average: ${average}`;
